css:
.naarni-report { font-family: 'Helvetica Neue', Arial, sans-serif; color: #1a2233; position: relative; }
.wm { position: fixed; top: 38%; left: 0; right: 0; text-align: center; font-size: 120px; font-weight: 800; color: #0a5; opacity: 0.05; transform: rotate(-28deg); letter-spacing: 8px; z-index: 0; }
.naarni-report > *:not(.wm) { position: relative; z-index: 1; }
.hd { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #0a5; padding-bottom: 12px; margin-bottom: 4px; }
.logo { font-size: 30px; font-weight: 800; color: #0a5; letter-spacing: -1px; }
.logo span { color: #1a2233; }
.tag { font-size: 11px; color: #6b7280; margin-top: 2px; }
.meta { text-align: right; }
.title { font-size: 18px; font-weight: 700; }
.sub { font-size: 11px; color: #6b7280; }
.ribbon { display: inline-block; background: #0a5; color: #fff; font-size: 10px; font-weight: 700; padding: 3px 10px; border-radius: 3px; margin: 10px 0 14px; letter-spacing: 0.5px; text-transform: uppercase; }
.grid2 { display: flex; gap: 12px; }
.grid2 .card { flex: 1; }
.card { border: 1px solid #e5e7eb; border-radius: 8px; padding: 12px 14px; margin-bottom: 12px; background: #fff; }
.ch { font-size: 12px; font-weight: 700; color: #0a5; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
table.kv { width: 100%; font-size: 12px; border-collapse: collapse; }
table.kv td { padding: 4px 0; vertical-align: top; }
table.kv td:first-child { color: #6b7280; width: 38%; }
table.kv td:last-child { font-weight: 600; }
table.kv.wide td:first-child { width: 30%; }
table.tbl { width: 100%; border-collapse: collapse; font-size: 11px; margin-top: 6px; }
table.tbl th { background: #f0fdf6; color: #065f3a; text-align: left; padding: 6px 8px; border-bottom: 2px solid #0a5; font-size: 10px; text-transform: uppercase; }
table.tbl td { padding: 6px 8px; border-bottom: 1px solid #eef1f4; }
table.tbl .r { text-align: right; }
.scores { display: flex; gap: 10px; margin-bottom: 10px; }
.score { flex: 1; text-align: center; background: #f8fafc; border-radius: 8px; padding: 10px; }
.score .sv { font-size: 22px; font-weight: 800; color: #1a2233; }
.score.up .sv { color: #0a5; }
.score .sl { font-size: 10px; color: #6b7280; text-transform: uppercase; }
.photos { display: flex; flex-wrap: wrap; gap: 8px; }
.ph { width: 120px; }
.ph img { width: 120px; height: 90px; object-fit: cover; border-radius: 6px; border: 1px solid #e5e7eb; }
.pl { font-size: 10px; text-align: center; color: #6b7280; margin-top: 2px; }
.signoff { display: flex; gap: 40px; margin-top: 28px; }
.sg { flex: 1; font-size: 11px; color: #6b7280; }
.sg .line { border-top: 1px solid #94a3b8; margin-bottom: 4px; height: 30px; }
.ft { margin-top: 20px; padding-top: 10px; border-top: 1px solid #e5e7eb; font-size: 10px; color: #9ca3af; text-align: center; }
